solution.code:
async function cariProduk({ kategori, hargaMaks, kata } = {}) {
  const filter = {};
  if (kategori) filter.kategori = kategori;
  if (hargaMaks !== undefined) filter.harga = { $lte: hargaMaks };
  if (kata) filter.nama = { $regex: kata, $options: "i" };
  return await produk
    .find(filter)
    .sort({ harga: 1 })
    .project({ _id: 0, kode: 1, nama: 1, harga: 1 })
    .toArray();
}

async function prosesPesanan(kodePesanan) {
  const p = await pesanan.findOne({ kode: kodePesanan, status: "baru" });
  if (!p) return false;
  for (const it of p.item) {
    await produk.updateOne({ kode: it.produk }, { $inc: { stok: -it.jumlah } });
  }
  await pesanan.updateOne({ kode: kodePesanan }, { $set: { status: "diproses" } });
  return true;
}

async function omzetPerKategori() {
  return await pesanan
    .aggregate([
      { $match: { status: { $ne: "batal" } } },
      { $unwind: "$item" },
      { $group: { _id: "$item.kategori", total: { $sum: { $multiply: ["$item.harga", "$item.jumlah"] } } } },
      { $sort: { total: -1 } },
      { $project: { _id: 0, kategori: "$_id", total: 1 } },
    ])
    .toArray();
}

async function pelangganTeratas(n) {
  return await pesanan
    .aggregate([
      { $match: { status: { $ne: "batal" } } },
      { $unwind: "$item" },
      { $group: { _id: "$pelanggan", belanja: { $sum: { $multiply: ["$item.harga", "$item.jumlah"] } } } },
      { $sort: { belanja: -1 } },
      { $limit: n },
      { $lookup: { from: "pelanggan", localField: "_id", foreignField: "kode", as: "info" } },
      { $unwind: "$info" },
      { $project: { _id: 0, nama: "$info.nama", belanja: 1 } },
    ])
    .toArray();
}

async function halamanProduk(halaman, perHalaman) {
  const rows = await produk
    .find({})
    .sort({ nama: 1 })
    .skip((halaman - 1) * perHalaman)
    .limit(perHalaman)
    .project({ _id: 0, nama: 1 })
    .toArray();
  return rows.map((p) => p.nama);
}

project.setup:
// mini-mongo: in-memory MongoDB look-alike for exercises. Paste into `setup`.
// db.collection(nama) -> insertOne/insertMany/find/findOne/updateOne/updateMany/deleteOne/deleteMany/countDocuments/aggregate/createIndex
// Results are plain values (await still works). find() returns a cursor: sort/skip/limit/project/toArray.
const db = (() => {
  const data = {};
  let seq = 0;
  const get = (doc, path) => path.split(".").reduce((v, k) => (v == null ? undefined : Array.isArray(v) && isNaN(k) ? v.map((x) => x?.[k]).flat() : v[k]), doc);
  const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
  const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
  const isOp = (v) => v && typeof v === "object" && !Array.isArray(v) && Object.keys(v).some((k) => k.startsWith("$"));
  function test(val, cond) {
    if (!isOp(cond)) return Array.isArray(val) && !Array.isArray(cond) ? val.some((x) => eq(x, cond)) : eq(val, cond);
    return Object.entries(cond).every(([op, arg]) => {
      const any = (f) => (Array.isArray(val) ? val.some(f) || f(val) : f(val));
      switch (op) {
        case "$eq": return test(val, arg);
        case "$ne": return !test(val, arg);
        case "$gt": return any((x) => x != null && x > arg);
        case "$gte": return any((x) => x != null && x >= arg);
        case "$lt": return any((x) => x != null && x < arg);
        case "$lte": return any((x) => x != null && x <= arg);
        case "$in": return arg.some((a) => test(val, a));
        case "$nin": return !arg.some((a) => test(val, a));
        case "$exists": return (val !== undefined) === arg;
        case "$regex": return any((x) => typeof x === "string" && new RegExp(arg, cond.$options || "").test(x));
        case "$options": return true;
        case "$size": return Array.isArray(val) && val.length === arg;
        case "$all": return Array.isArray(val) && arg.every((a) => val.some((x) => eq(x, a)));
        case "$elemMatch": return Array.isArray(val) && val.some((x) => match(x, arg) || (!isOp(x) && test(x, arg)));
        default: throw new Error("operator tidak didukung: " + op);
      }
    });
  }
  function match(doc, q = {}) {
    return Object.entries(q).every(([k, v]) => {
      if (k === "$and") return v.every((s) => match(doc, s));
      if (k === "$or") return v.some((s) => match(doc, s));
      if (k === "$nor") return !v.some((s) => match(doc, s));
      return test(get(doc, k), v);
    });
  }
  const clone = (x) => JSON.parse(JSON.stringify(x));
  function setPath(doc, path, val) {
    const ks = path.split("."); let o = doc;
    ks.slice(0, -1).forEach((k) => (o = o[k] ??= {}));
    o[ks.at(-1)] = val;
  }
  function unsetPath(doc, path) {
    const ks = path.split("."); const o = ks.slice(0, -1).reduce((v, k) => v?.[k], doc);
    if (o) delete o[ks.at(-1)];
  }
  function applyUpdate(doc, u) {
    for (const [op, fields] of Object.entries(u)) for (const [k, v] of Object.entries(fields)) {
      if (op === "$set") setPath(doc, k, clone(v));
      else if (op === "$inc") setPath(doc, k, (get(doc, k) ?? 0) + v);
      else if (op === "$unset") unsetPath(doc, k);
      else if (op === "$push") setPath(doc, k, [...(get(doc, k) ?? []), clone(v)]);
      else if (op === "$pull") setPath(doc, k, (get(doc, k) ?? []).filter((x) => !test(x, v)));
      else throw new Error("operator update tidak didukung: " + op);
    }
  }
  function project(doc, p) {
    if (!p || !Object.keys(p).length) return doc;
    const incl = Object.entries(p).filter(([k, v]) => k !== "_id" && v);
    if (incl.length) {
      const out = p._id === 0 ? {} : { _id: doc._id };
      for (const [k] of incl) { const v = get(doc, k); if (v !== undefined) setPath(out, k, v); }
      return out;
    }
    const out = clone(doc);
    for (const [k, v] of Object.entries(p)) if (!v) unsetPath(out, k);
    return out;
  }
  const sorter = (s) => (a, b) => { for (const [k, d] of Object.entries(s)) { const c = cmp(get(a, k), get(b, k)); if (c) return c * d; } return 0; };
  function cursor(rows) {
    let s = null, sk = 0, lim = 0, p = null;
    const c = {
      sort: (x) => ((s = x), c), skip: (n) => ((sk = n), c), limit: (n) => ((lim = n), c), project: (x) => ((p = x), c),
      toArray: () => { let r = rows.slice(); if (s) r.sort(sorter(s)); r = r.slice(sk, lim ? sk + lim : undefined); return r.map((d) => project(clone(d), p)); },
    };
    return c;
  }
  function expr(doc, e) {
    if (typeof e === "string" && e.startsWith("$")) return get(doc, e.slice(1));
    if (e && typeof e === "object" && !Array.isArray(e)) {
      const [op, a] = Object.entries(e)[0];
      const v = Array.isArray(a) ? a.map((x) => expr(doc, x)) : expr(doc, a);
      switch (op) {
        case "$add": return v.reduce((x, y) => x + y, 0);
        case "$subtract": return v[0] - v[1];
        case "$multiply": return v.reduce((x, y) => x * y, 1);
        case "$divide": return v[0] / v[1];
        case "$concat": return v.join("");
        case "$toUpper": return String(v).toUpperCase();
        case "$size": return v.length;
        default: return e;
      }
    }
    return e;
  }
  function aggregate(rows, pipeline) {
    let r = rows.map(clone);
    for (const stage of pipeline) {
      const [op, a] = Object.entries(stage)[0];
      if (op === "$match") r = r.filter((d) => match(d, a));
      else if (op === "$sort") r.sort(sorter(a));
      else if (op === "$limit") r = r.slice(0, a);
      else if (op === "$skip") r = r.slice(a);
      else if (op === "$count") r = [{ [a]: r.length }];
      else if (op === "$unwind") { const k = (typeof a === "string" ? a : a.path).slice(1); r = r.flatMap((d) => (get(d, k) ?? []).map((x) => { const c = clone(d); setPath(c, k, x); return c; })); }
      else if (op === "$project" || op === "$addFields" || op === "$set") {
        r = r.map((d) => {
          const keep = op === "$project" && Object.values(a).some((v) => v === 1 || v === true);
          const out = op === "$project" ? (keep ? (a._id === 0 ? {} : { _id: d._id }) : clone(d)) : clone(d);
          for (const [k, v] of Object.entries(a)) {
            if (v === 0 || v === false) unsetPath(out, k);
            else if (v === 1 || v === true) { if (k !== "_id") setPath(out, k, get(d, k)); }
            else setPath(out, k, expr(d, v));
          }
          return out;
        });
      } else if (op === "$group") {
        const groups = new Map();
        for (const d of r) {
          const id = expr(d, a._id); const key = JSON.stringify(id ?? null);
          if (!groups.has(key)) groups.set(key, { _id: id ?? null, _rows: [] });
          groups.get(key)._rows.push(d);
        }
        r = [...groups.values()].map((g) => {
          const out = { _id: g._id };
          for (const [k, acc] of Object.entries(a)) {
            if (k === "_id") continue;
            const [fn, e] = Object.entries(acc)[0];
            const vals = g._rows.map((d) => expr(d, e));
            out[k] = fn === "$sum" ? vals.reduce((x, y) => x + (typeof y === "number" ? y : 0), 0)
              : fn === "$avg" ? vals.reduce((x, y) => x + y, 0) / vals.length
              : fn === "$min" ? Math.min(...vals) : fn === "$max" ? Math.max(...vals)
              : fn === "$push" ? vals : fn === "$addToSet" ? [...new Set(vals.map((v) => JSON.stringify(v)))].map((v) => JSON.parse(v))
              : fn === "$first" ? vals[0] : fn === "$last" ? vals.at(-1)
              : (() => { throw new Error("akumulator tidak didukung: " + fn); })();
          }
          return out;
        });
      } else if (op === "$lookup") {
        const other = data[a.from] ?? [];
        r = r.map((d) => ({ ...d, [a.as]: other.filter((o) => test(get(o, a.foreignField), get(d, a.localField))).map(clone) }));
      } else throw new Error("tahap pipeline tidak didukung: " + op);
    }
    return r;
  }
  return {
    collection(name) {
      const rows = (data[name] ??= []);
      const indexes = [];
      const one = (q) => rows.find((d) => match(d, q));
      return {
        insertOne(doc) { const d = clone(doc); d._id ??= ++seq; for (const ix of indexes) if (ix.unique && rows.some((r) => eq(get(r, ix.key), get(d, ix.key)))) throw Object.assign(new Error("E11000 duplicate key error: " + ix.key), { code: 11000 }); rows.push(d); return { acknowledged: true, insertedId: d._id }; },
        insertMany(docs) { return { acknowledged: true, insertedCount: docs.map((d) => this.insertOne(d)).length }; },
        find: (q = {}, opt = {}) => { const c = cursor(rows.filter((d) => match(d, q))); return opt.projection ? c.project(opt.projection) : c; },
        findOne: (q = {}, opt = {}) => { const d = one(q); return d ? project(clone(d), opt.projection) : null; },
        countDocuments: (q = {}) => rows.filter((d) => match(d, q)).length,
        updateOne(q, u, opt = {}) { const d = one(q); if (d) { applyUpdate(d, u); return { matchedCount: 1, modifiedCount: 1 }; } if (opt.upsert) { const n = {}; for (const [k, v] of Object.entries(q)) if (!k.startsWith("$") && !isOp(v)) setPath(n, k, v); applyUpdate(n, u); this.insertOne(n); return { matchedCount: 0, modifiedCount: 0, upsertedCount: 1 }; } return { matchedCount: 0, modifiedCount: 0 }; },
        updateMany(q, u) { const ds = rows.filter((d) => match(d, q)); ds.forEach((d) => applyUpdate(d, u)); return { matchedCount: ds.length, modifiedCount: ds.length }; },
        deleteOne(q) { const i = rows.findIndex((d) => match(d, q)); if (i >= 0) rows.splice(i, 1); return { deletedCount: i >= 0 ? 1 : 0 }; },
        deleteMany(q = {}) { const before = rows.length; for (let i = rows.length - 1; i >= 0; i--) if (match(rows[i], q)) rows.splice(i, 1); return { deletedCount: before - rows.length }; },
        aggregate: (p) => ({ toArray: () => aggregate(rows, p) }),
        createIndex(spec, opt = {}) { const key = Object.keys(spec)[0]; indexes.push({ key, unique: !!opt.unique }); return Object.entries(spec).map(([k, v]) => `${k}_${v}`).join("_"); },
        indexes: () => indexes.slice(),
      };
    },
  };
})();
const produk = db.collection("produk");
const pelanggan = db.collection("pelanggan");
const pesanan = db.collection("pesanan");
produk.insertMany([
  { kode: "A01", nama: "Kaos Polos Hitam", kategori: "pakaian", harga: 65000, stok: 40 },
  { kode: "A02", nama: "Hoodie Matcha", kategori: "pakaian", harga: 180000, stok: 12 },
  { kode: "B01", nama: "Tumbler 500 ml", kategori: "aksesoris", harga: 55000, stok: 25 },
