function jadikanDokumen(siswaList, nilaiList) {
  return siswaList.map((s) => ({
    nis: s.nis,
    nama: s.nama,
    kelas: s.kelas,
    nilai: nilaiList
      .filter((n) => n.nis === s.nis)
      .map((n) => ({ mapel: n.mapel, skor: n.skor })),
  }));
}

