async function daftarJudul() {
  return await buku.find({}, { projection: { _id: 0, judul: 1 } }).toArray();
}

async function pinjam(judul, nama) {
  const r = await buku.updateOne(
    { judul },
    { $inc: { stok: -1 }, $push: { peminjam: nama } }
  );
  return r.modifiedCount;
}

async function tambahBuku(judul, penulis) {
  const r = await buku.insertOne({ judul, penulis, stok: 1, peminjam: [] });
  return r.insertedId;
}

async function hapusKosong() {
  const r = await buku.deleteMany({ stok: 0 });
  return r.deletedCount;
}

