  return nama(await menu.find({ harga: { $lte: maks }, stok: { $gt: 0 } }).sort({ harga: 1 }).toArray());
}

async function diLantai(n) {
  return nama(await menu.find({ "penjual.lantai": n }).sort({ nama: 1 }).toArray());
}

async function denganTag(daftar) {
  return nama(await menu.find({ tag: { $all: daftar } }).sort({ nama: 1 }).toArray());
}

async function halaman(nomor, per) {
  return nama(await menu.find({}).sort({ nama: 1 }).skip((nomor - 1) * per).limit(per).toArray());
}

