solution.code:
function gabung(pesananList, itemList) {
  return pesananList.map((p) => {
    const item = itemList
      .filter((i) => i.pesanan_id === p.id)
      .map((i) => ({ menu: i.menu, jumlah: i.jumlah, harga: i.harga }));
    const total = item.reduce((s, i) => s + i.jumlah * i.harga, 0);
    return { _id: p.id, siswa: p.siswa, tanggal: p.tanggal, item, total };
  });
}

function pilihPola({ jumlahAnak, dibacaBersama }) {
  return dibacaBersama && jumlahAnak <= 100 ? "embed" : "reference";
}

