async function omzetPerKategori() {
  return await transaksi.aggregate([
    { $unwind: "$item" },
    { $group: { _id: "$item.kategori", total: { $sum: { $multiply: ["$item.harga", "$item.jumlah"] } } } },
    { $sort: { total: -1 } },
    { $project: { _id: 0, kategori: "$_id", total: 1 } },
  ]).toArray();
}

async function transaksiPerKasir() {
  return await transaksi.aggregate([
    { $group: { _id: "$kasir", jumlah: { $sum: 1 } } },
    { $sort: { _id: 1 } },
  ]).toArray();
}

async function menuTerlaris(n) {
  return await transaksi.aggregate([
    { $unwind: "$item" },
    { $group: { _id: "$item.menu", porsi: { $sum: "$item.jumlah" } } },
    { $sort: { porsi: -1 } },
    { $limit: n },
  ]).toArray();
}

async function kasirDenganKelas() {
  return await kasir.aggregate([
    { $lookup: { from: "transaksi", localField: "nama", foreignField: "kasir", as: "riwayat" } },
    { $project: { _id: 0, nama: 1, kelas: 1, jumlah: { $size: "$riwayat" } } },
  ]).toArray();
}

