solution.code:
function ringkasExplain(hasil) {
  const tahap = [];
  let plan = hasil.queryPlanner.winningPlan;
  while (plan) {
    tahap.push(plan.stage);
    plan = plan.inputStage;
  }
  const s = hasil.executionStats;
  return {
    tahap,
    pakaiIndex: tahap.includes("IXSCAN"),
    rasio: s.totalDocsExamined / Math.max(s.nReturned, 1),
  };
}

