solution.code:
function buatDokumen(skema, data) {
  const doc = { ...data };
  const errors = [];
  for (const [field, aturan] of Object.entries(skema)) {
    if (doc[field] === undefined && "default" in aturan) doc[field] = aturan.default;
    const v = doc[field];
    if (v === undefined || v === null || v === "") {
      if (aturan.required) errors.push(`${field} wajib diisi`);
      continue;
    }
    const tipe = aturan.type === String ? "string" : "number";
    if (typeof v !== tipe) {
      errors.push(`${field} harus bertipe ${aturan.type.name}`);
      continue;
    }
    if (aturan.min !== undefined && v < aturan.min) errors.push(`${field} minimal ${aturan.min}`);
    if (aturan.max !== undefined && v > aturan.max) errors.push(`${field} maksimal ${aturan.max}`);
    if (aturan.enum && !aturan.enum.includes(v)) errors.push(`${field} harus salah satu dari: ${aturan.enum.join(", ")}`);
  }
  if (errors.length) throw new Error(errors.join("; "));
  return doc;
}

