solution.code:
async function checkout(keranjang) {
  for (const item of keranjang) {
    const p = await produk.findOne({ kode: item.kode });
    if (!p || p.stok < item.jumlah) throw new Error("Stok tidak cukup: " + item.kode);
  }
  for (const item of keranjang) {
    await produk.updateOne({ kode: item.kode }, { $inc: { stok: -item.jumlah } });
  }
  const hasil = await pesanan.insertOne({ item: keranjang, status: "baru" });
  return hasil.insertedId;
}

